// Bộ chạy test tối giản: hiểu test runner thực chất chỉ là vậy
const results = [];
async function test(name, fn) {
  try { await fn(); results.push("✓ " + name); }
  catch (e) { results.push("✗ " + name + ": " + e.message); }
}
const assert = require("assert");

const add = (a, b) => a + b;

(async () => {
  await test("cộng hai số", () => assert.strictEqual(add(2, 3), 5));
  await test("cố ý sai", () => assert.strictEqual(add(2, 2), 5));
  console.log(results.join("\n"));
})();

